78	# MoveFileExW for Windows PowerShell 5.1, whose .NET Framework has no File.Move with
79	# overwrite: compiled once per process on first use (Add-Type, ~0.2 s) and cached. $true
80	# when [CodexConsultNative]::MoveFileEx is available.
81	$script:NativeMoveReady = $null
82	function Test-NativeMove {
83	    if ($null -ne $script:NativeMoveReady) { return $script:NativeMoveReady }
84	    $script:NativeMoveReady = $false
85	    try {
86	        if (-not ('CodexConsultNative' -as [type])) {
87	            Add-Type -TypeDefinition @'
88	using System;
89	using System.Runtime.InteropServices;
90	public static class CodexConsultNative {
91	    [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode, EntryPoint = "MoveFileExW")]
92	    public static extern bool MoveFileEx(string existingFileName, string newFileName, int flags);
93	}
94	'@
95	        }
96	        $script:NativeMoveReady = $true
97	    } catch { }
98	    return $script:NativeMoveReady
99	}
