101	# Replaces $Path with $Text (UTF-8, no BOM) atomically: the text is written and flushed
102	# to disk (FileStream.Flush($true)) in a temp file .<name>.<guid>.tmp NEXT TO the
103	# destination (same volume), which then replaces the destination in ONE rename:
104	#   PowerShell 7 (Windows, macOS, Linux)  [IO.File]::Move($tmp, $dst, $true) - on
105	#       Windows MoveFileEx(MOVEFILE_REPLACE_EXISTING), elsewhere rename(2)
106	#   Windows PowerShell 5.1                MoveFileExW(MOVEFILE_REPLACE_EXISTING |
107	#       MOVEFILE_WRITE_THROUGH) through Test-NativeMove; only if Add-Type fails, the old
108	#       path: File.Move when the destination does not exist, else File.Replace
109	#       (ReplaceFile - NOT one atomic step: a process killed inside it can leave the
110	#       destination missing and the new text in the temp file)
111	# A crash leaves either the old or the new file, never a truncated or a missing one (at
112	# worst a stray .<name>.<guid>.tmp next to it). A rename that keeps failing (a reader
113	# holding the destination open without FileShare.Delete) is retried, then the temp file
114	# is removed and the error thrown.
115	function Write-TextAtomic {
116	    param([string]$Path, [string]$Text)
117	    $full = [IO.Path]::GetFullPath($Path)
118	    $dir = [IO.Path]::GetDirectoryName($full)
119	    $tmp = Join-Path $dir ('.' + [IO.Path]::GetFileName($full) + '.' + [guid]::NewGuid().ToString('N') + '.tmp')
120	    $bytes = $script:Utf8NoBom.GetBytes($Text)
121	    $fs = New-Object System.IO.FileStream($tmp, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
122	    try {
123	        $fs.Write($bytes, 0, $bytes.Length)
124	        $fs.Flush($true)
125	    } finally { $fs.Dispose() }
126	    $lastError = $null
127	    for ($attempt = 1; $attempt -le 8; $attempt++) {
128	        try {
129	            if (-not $script:LegacyPS) {
130	                [IO.File]::Move($tmp, $full, $true)
131	            } elseif (Test-NativeMove) {
132	                # MOVEFILE_REPLACE_EXISTING (0x1) | MOVEFILE_WRITE_THROUGH (0x8)
133	                if (-not [CodexConsultNative]::MoveFileEx($tmp, $full, 0x9)) {
134	                    throw (New-Object System.ComponentModel.Win32Exception([Runtime.InteropServices.Marshal]::GetLastWin32Error()))
135	                }
136	            } elseif (-not [IO.File]::Exists($full)) {
137	                [IO.File]::Move($tmp, $full)
138	            } else {
139	                # Fallback only when Add-Type failed (see above): not one atomic step.
140	                # $null would reach .NET as '' - NullString is a real null (no backup file).
141	                [IO.File]::Replace($tmp, $full, [System.Management.Automation.Language.NullString]::Value)
142	            }
143	            return
144	        } catch {
145	            # A reader holding the destination open without FileShare.Delete makes the
146	            # rename fail with a sharing violation; it is gone a moment later.
147	            $lastError = $_.Exception
148	            Start-Sleep -Milliseconds 250
149	        }
150	    }
151	    try { [IO.File]::Delete($tmp) } catch { }
152	    throw "could not replace '$full': $($lastError.Message)"
153	}
