200	# Start-Process holds the stdout/stderr redirection handles for a short while after
201	# the child exits, so a plain Get-Content can fail with "the process cannot access
202	# the file ... because it is being used by another process" - observed on a
203	# fast-failing codex run. Read with FileShare.ReadWrite (+ Delete, so an atomic
204	# replace of the file is not blocked by this reader) and retry briefly.
205	function Read-SharedText {
206	    param([string]$Path)
207	    if (-not (Test-Path -LiteralPath $Path)) { return '' }
208	    for ($attempt = 1; $attempt -le 6; $attempt++) {
209	        try {
210	            $fs = New-Object System.IO.FileStream($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, ([System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete))
211	            try {
212	                $sr = New-Object System.IO.StreamReader($fs, (New-Object System.Text.UTF8Encoding($false)), $true)
213	                try { return $sr.ReadToEnd() } finally { $sr.Dispose() }
214	            } finally { $fs.Dispose() }
215	        } catch {
216	            Start-Sleep -Milliseconds 250
217	        }
218	    }
219	    return ''
220	}
624	function Get-CollabSnapshot {
625	    param([string]$Dir)
626	    # ordinal keys: a.md and A.md are two files on a case-sensitive filesystem
627	    $snap = New-Object System.Collections.Hashtable ([StringComparer]::Ordinal)
628	    if (-not $Dir -or -not [IO.Directory]::Exists($Dir)) { return $snap }
629	    $root = [IO.Path]::GetFullPath($Dir).TrimEnd([char]'\', [char]'/')
630	    $stack = New-Object System.Collections.Generic.Stack[string]
631	    $stack.Push($root)
632	    while ($stack.Count -gt 0) {
633	        $d = $stack.Pop()
634	        $info = New-Object System.IO.DirectoryInfo($d)
635	        $files = @()
636	        $subdirs = @()
637	        try { $files = @($info.GetFiles()); $subdirs = @($info.GetDirectories()) } catch { continue }
638	        foreach ($f in $files) {
639	            if ($f.Name.StartsWith('.consult.', [StringComparison]::OrdinalIgnoreCase) -or $f.Name.StartsWith('..consult.', [StringComparison]::OrdinalIgnoreCase)) { continue }
640	            $rel = $f.FullName.Substring($root.Length).TrimStart([char]'\', [char]'/').Replace('\', '/')
641	            $snap[$rel] = "$($f.Length)|$(Get-FileSha256OrMissing -Path $f.FullName)"
642	        }
