679	# Built artifacts to bind a review to: resolves each path (as given, relative to one
680	# of $Bases or absolute) to { path = as given; full = absolute path }. A missing
681	# artifact stops the run - the caller asked to bind the review to it, silently
682	# skipping it would defeat the binding. Hashing happens separately (under the task
683	# lock, and again after the run). Emits one object per artifact; collect with @(...).
684	function Resolve-ArtifactPaths {
685	    param([string[]]$Paths, [string[]]$Bases)
686	    foreach ($raw in @($Paths)) {
687	        if (-not $raw) { continue }
688	        $resolved = $null
689	        if ([IO.Path]::IsPathRooted($raw)) {
690	            if (Test-Path -LiteralPath $raw -PathType Leaf) { $resolved = $raw }
691	        } else {
