757	            $ledgerNs[$v] = $true
758	            if ($v -gt $maxN) { $maxN = $v }
759	        }
760	    }
761	    $maxNn = 0
762	    if ($HandoffsDir -and (Test-Path -LiteralPath $HandoffsDir)) {
763	        foreach ($file in @(Get-ChildItem -LiteralPath $HandoffsDir -File -ErrorAction SilentlyContinue)) {
764	            $v = 0
765	            if ($file.Name -match '^(\d{2,})-' -and [int]::TryParse($Matches[1], [ref]$v) -and $v -gt $maxNn) { $maxNn = $v }
766	        }
767	    }
768	    if ($Store) {
769	        foreach ($f in @($Store.findings | Where-Object { $null -ne $_ })) {
770	            $v = 0
771	            $src = Get-PropertyValue $f 'source' $null
772	            if ($src -and [int]::TryParse([string](Get-PropertyValue $src 'consult' ''), [ref]$v) -and $v -gt $maxN) { $maxN = $v }
773	            foreach ($rc in @(Get-PropertyValue $f 'reviewer_checks' @())) {
774	                $v = 0
775	                if ($rc -and [int]::TryParse([string](Get-PropertyValue $rc 'consult' ''), [ref]$v) -and $v -gt $maxN) { $maxN = $v }
776	            }
777	            $v = 0
778	            if ([string](Get-PropertyValue $f 'id' '') -match '^F(\d{2,})-\d+$' -and [int]::TryParse($Matches[1], [ref]$v) -and $v -gt $maxNn) { $maxNn = $v }
779	        }
780	    }
