4347	# Do two start times (UTC round-trip strings from Get-ProcessStartIso) name the same
4348	# process start? Windows reports a process's start time exactly. .NET on Linux derives
4349	# Process.StartTime from a boot time that every process computes for itself
4350	# (CLOCK_REALTIME_COARSE - CLOCK_BOOTTIME), so two processes reading the SAME pid get
4351	# values a few milliseconds apart. Outside Windows, less than one second apart counts
4352	# as the same start (a pid is not handed out again that fast).
4353	function Test-SameStartTime {
4354	    param([string]$A, [string]$B)
4355	    if ($A -eq $B) { return $true }
4356	    if ($script:OnWindows) { return $false }
4357	    $ta = [DateTimeOffset]::MinValue
4358	    $tb = [DateTimeOffset]::MinValue
4359	    $styles = [System.Globalization.DateTimeStyles]::AssumeUniversal
4360	    if (-not [DateTimeOffset]::TryParse($A, $script:Invariant, $styles, [ref]$ta)) { return $false }
4361	    if (-not [DateTimeOffset]::TryParse($B, $script:Invariant, $styles, [ref]$tb)) { return $false }
4362	    return ([math]::Abs($ta.UtcTicks - $tb.UtcTicks) -lt [TimeSpan]::TicksPerSecond)
4363	}
