624	function Get-CollabSnapshot {
625	    param([string]$Dir)
626	    # ordinal keys: a.md and A.md are two files on a case-sensitive filesystem
627	    $snap = New-Object System.Collections.Hashtable ([StringComparer]::Ordinal)
628	    if (-not $Dir -or -not [IO.Directory]::Exists($Dir)) { return $snap }
629	    $root = [IO.Path]::GetFullPath($Dir).TrimEnd([char]'\', [char]'/')
630	    $stack = New-Object System.Collections.Generic.Stack[string]
631	    $stack.Push($root)
632	    while ($stack.Count -gt 0) {
633	        $d = $stack.Pop()
634	        $info = New-Object System.IO.DirectoryInfo($d)
635	        $files = @()
636	        $subdirs = @()
637	        try { $files = @($info.GetFiles()); $subdirs = @($info.GetDirectories()) } catch { continue }
638	        foreach ($f in $files) {
639	            if ($f.Name.StartsWith('.consult.', [StringComparison]::OrdinalIgnoreCase) -or $f.Name.StartsWith('..consult.', [StringComparison]::OrdinalIgnoreCase)) { continue }
640	            $rel = $f.FullName.Substring($root.Length).TrimStart([char]'\', [char]'/').Replace('\', '/')
641	            $snap[$rel] = "$($f.Length)|$(Get-FileSha256OrMissing -Path $f.FullName)"
642	        }
643	        foreach ($s in $subdirs) {
644	            if ($s.Name -eq '.git') { continue }
645	            if (($s.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { continue }
646	            $stack.Push($s.FullName)
647	        }
648	    }
649	    return $snap
650	}
