683	# lock, and again after the run). Emits one object per artifact; collect with @(...).
684	function Resolve-ArtifactPaths {
1284	function Add-ReplyFindings {
1285	    param(
1286	        $Store,
1287	        $Reply,
1288	        [string]$Nn,
1289	        [int]$ConsultN,
1290	        [string]$ReplyRel,
1291	        [string]$ThreadId,
1292	        [string]$BaseCommit,
1293	        [string]$TreeSha256,
1294	        [string[]]$ListedIds = @(),
1295	        [string]$When = ''
1296	    )
1297	    if (-not $When) { $When = Get-IsoTimestamp }
1298	    $existing = @{}
1299	    foreach ($f in @($Store.findings)) {
1300	        if ($null -ne $f -and $f.PSObject.Properties['id']) { $existing[[string]$f.id] = $f }
1301	    }
1302	    # Open prior blockers the reply does not report fixed stay blockers: they are
1303	    # rendered with the new ones (no new finding record is created for them).
1304	    $priorInfo = @(foreach ($listed in @($ListedIds | Where-Object { $_ })) {
1305	            if ($existing.ContainsKey($listed)) {
1306	                $rec = $existing[$listed]
1307	                [pscustomobject]@{ id = [string]$rec.id; severity = [string](Get-PropertyValue $rec 'severity' ''); status = [string](Get-PropertyValue $rec 'status' '') }
1308	            }
1309	        })
1310	    $retained = @(foreach ($d in @(Get-PriorBlockerDispositions -Reply $Reply -PriorFindings $priorInfo)) {
1311	            if ($d.disposition -eq 'fixed') { continue }
1312	            [pscustomobject]@{ id = $d.id; disposition = $d.disposition; record = $existing[$d.id] }
1313	        })
1314	    $newIds = New-Object System.Collections.Generic.List[string]
1315	    $newRecords = New-Object System.Collections.Generic.List[object]
1316	    $k = 0
1317	    foreach ($f in @($Reply.findings)) {
1318	        $k++
1319	        $id = "F$Nn-$k"
1320	        $newIds.Add($id)
1321	        $newRecords.Add([pscustomobject]@{
1322	                id              = $id
1323	                status          = 'proposed'
1324	                severity        = $f.severity
1325	                locations       = [object[]]@($f.locations)
1326	                claim           = $f.claim
1327	                trigger         = $f.trigger
1328	                evidence        = [object[]]@($f.evidence)
1329	                verification    = $f.verification
1330	                remedy          = $f.remedy
1331	                supersedes      = [object[]]@($f.supersedes)
1332	                superseded_by   = [object[]]@()
1333	                source          = [pscustomobject]@{
1334	                    consult     = $ConsultN
1335	                    reply       = $ReplyRel
1336	                    thread      = $ThreadId
1337	                    base_commit = $BaseCommit
1338	                    tree_sha256 = $TreeSha256
1339	                }
1340	                history         = [object[]]@([pscustomobject]@{
1341	                        when        = $When
1342	                        status      = 'proposed'
1343	                        by          = 'codex-consult'
1344	                        note        = ''
1345	                        evidence    = ''
1346	                        base_commit = $BaseCommit
1347	                        tree_sha256 = $TreeSha256
1348	                    })
1349	                reviewer_checks = [object[]]@()
1350	            })
1351	    }
1352	    $changed = ($newRecords.Count -gt 0)
1353	
1354	    $unknownSupersedes = New-Object System.Collections.Generic.List[string]
1355	    foreach ($rec in $newRecords) {
1356	        foreach ($old in @($rec.supersedes)) {
1357	            if ($existing.ContainsKey([string]$old)) {
1358	                $target = $existing[[string]$old]
1359	                $already = @(Get-PropertyValue $target 'superseded_by' @()) -contains $rec.id
1360	                if (-not $already) { Add-ArrayItem -Object $target -Name 'superseded_by' -Item $rec.id; $changed = $true }
1361	            } else {
1362	                $unknownSupersedes.Add([string]$old)
1363	            }
1364	        }
1365	    }
1366	
1367	    $priorEntries = New-Object System.Collections.Generic.List[object]
1368	    $unknownIds = New-Object System.Collections.Generic.List[string]
1369	    $reported = @{}
1370	    foreach ($p in @($Reply.prior_findings)) {
1371	        $priorId = [string]$p.id
1372	        $reported[$priorId] = $true
1373	        $known = $existing.ContainsKey($priorId)
1374	        $priorEntries.Add([pscustomobject]@{ id = $priorId; status = $p.status; note = $p.note; known = $known })
1375	        if ($known) {
1376	            Add-ArrayItem -Object $existing[$priorId] -Name 'reviewer_checks' -Item ([pscustomobject]@{
1377	                    consult     = $ConsultN
1378	                    when        = $When
1379	                    status      = $p.status
1380	                    note        = $p.note
1381	                    base_commit = $BaseCommit
1382	                    tree_sha256 = $TreeSha256
1383	                })
1384	            $changed = $true
1385	        } else {
1386	            $unknownIds.Add($priorId)
1387	        }
1388	    }
1389	    $notReported = New-Object System.Collections.Generic.List[string]
1390	    foreach ($listed in @($ListedIds | Where-Object { $_ })) {
1391	        if ($reported.ContainsKey($listed) -or -not $existing.ContainsKey($listed)) { continue }
1392	        $notReported.Add($listed)
1393	        $priorEntries.Add([pscustomobject]@{ id = $listed; status = 'not-checked'; note = '(not reported)'; known = $true })
1394	        Add-ArrayItem -Object $existing[$listed] -Name 'reviewer_checks' -Item ([pscustomobject]@{
1395	                consult     = $ConsultN
1396	                when        = $When
1397	                status      = 'not-checked'
1398	                note        = '(not reported)'
1399	                base_commit = $BaseCommit
1400	                tree_sha256 = $TreeSha256
1401	            })
1402	        $changed = $true
1403	    }
1404	
1405	    if ($newRecords.Count -gt 0) {
1406	        $Store.findings = [object[]](@($Store.findings | Where-Object { $null -ne $_ }) + $newRecords.ToArray())
1407	    }
1408	    return [pscustomobject]@{
1409	        NewIds            = [string[]]$newIds.ToArray()
1410	        PriorEntries      = [object[]]$priorEntries.ToArray()
1411	        UnknownIds        = [string[]]$unknownIds.ToArray()
1412	        NotReported       = [string[]]$notReported.ToArray()
1413	        UnknownSupersedes = [string[]]$unknownSupersedes.ToArray()
1414	        RetainedBlockers  = [object[]]$retained
1415	        Counts            = (Get-SeverityCounts -Findings $Reply.findings)
1416	        Changed           = $changed
1417	    }
1418	}
