3632	function ConvertTo-WhenOffset {
3633	    param($Value)
3634	    if ($Value -is [DateTimeOffset]) { return $Value }
3635	    if ($Value -is [datetime]) { return [DateTimeOffset]$Value }
3636	    $at = [DateTimeOffset]::MinValue
3637	    if ([DateTimeOffset]::TryParse([string]$Value, $script:Invariant, [System.Globalization.DateTimeStyles]::None, [ref]$at)) { return $at }
