3641	# Health of one ENDPOINT (provider_fingerprint - never the alias) from the ledgers of all
3642	# tasks. Entries recorded before 0.3.0 count as the built-in openai endpoint; entries with
3643	# an unresolved identity (empty fingerprint) are ignored. A failure's class comes from its
3644	# provider_failure, else (older entries) from its bridge_outcome. Newest wins: a later
3645	# successful run clears an earlier auth or quota failure. $UtcNow: the consult clock
3646	# (Get-ConsultClock -Peek), so a test can freeze time.
3647	#   Auth         the newest of {success, auth failure} is an auth failure <= 24 h old
3648	#   Quota        the newest of {success, quota failure} is a quota failure that still
3649	#                blocks: its RetryAfter lies in the future, or it has no RetryAfter and is
3650	#                <= 60 min old (a RetryAfter in the past clears it)
3651	#   QuotaKnown   [bool] Quota is set and names its reset time (RetryAfter)
3652	#   LastLimit    the newest quota failure <= 24 h old (informational)
3653	#   LastFailure  the newest failure of any class <= 24 h old (informational)
3654	#   RecentUsable the newest usable reply <= 60 min old (wave 18: an engine's sign-in is then
3655	#                evidenced without a network check - Get-EngineCredential)
3656	# Each record is $null or { Class; Code; Message; When; AgeMinutes (a `when` in the future
3657	# counts as now: 0); RetryAfter (DateTimeOffset or $null: provider_failure.retry_after, else
3658	# Get-RetryAfter -ReferenceOffset on the recorded message with the failure's `when` as
3659	# reference); RetryAfterIso ('' when none); RetryAfterBasis ('ledger' | 'message (reference
3660	# offset)' | ''); Until (RetryAfter, else When + 60 min) }.
3661	function Get-EndpointHealth {
3662	    param([object[]]$Consults, [string]$Fingerprint, [datetime]$UtcNow = [datetime]::UtcNow)
3663	    $h = [pscustomobject]@{ Auth = $null; Quota = $null; QuotaKnown = $false; LastLimit = $null; LastFailure = $null; RecentUsable = $null }
3664	    if (-not $Fingerprint) { return $h }
3665	    $records = New-Object System.Collections.Generic.List[object]
3666	    foreach ($c in @($Consults | Where-Object { $null -ne $_ })) {
3667	        $rev = Get-PropertyValue $c 'reviewer' $null
3668	        $fp = if ($null -eq $rev) { $script:BuiltinOpenAiFingerprint } else { [string](Get-PropertyValue $rev 'provider_fingerprint' '') }
3669	        if (-not $fp -or $fp -ne $Fingerprint) { continue }
3670	        $outcome = [string](Get-PropertyValue $c 'bridge_outcome' '')
3671	        if (-not $outcome) { continue }
3672	        $at = ConvertTo-WhenOffset (Get-PropertyValue $c 'when' '')
3673	        if ($null -eq $at) { continue }
3674	        # A failure stamped in the future (clock skew, a mislabelled zone) counts as now:
3675	        # its age is clamped to 0, it is never skipped (F15-4).
3676	        $age = [Math]::Max(0, ($UtcNow - $at.UtcDateTime).TotalMinutes)
3677	        $rec = [pscustomobject]@{ At = $at; Ok = ($outcome -eq 'usable reply'); Class = ''; Code = ''; Message = ''; When = $at.ToString('yyyy-MM-ddTHH:mm:sszzz', $script:Invariant); AgeMinutes = [int][Math]::Max(0, [Math]::Floor($age)); Age = $age; RetryAfter = $null; RetryAfterIso = ''; RetryAfterBasis = ''; Until = $at.AddMinutes(60) }
3678	        if (-not $rec.Ok) {
3679	            $reference = $at
3680	            $pf = Get-PropertyValue $c 'provider_failure' $null
3681	            if ($null -ne $pf) {
3682	                $rec.Class = [string](Get-PropertyValue $pf 'class' 'unknown')
3683	                $rec.Code = [string](Get-PropertyValue $pf 'code' '')
3684	                $rec.Message = [string](Get-PropertyValue $pf 'message' '')
3685	                $pfWhen = ConvertTo-WhenOffset (Get-PropertyValue $pf 'when' '')
3686	                if ($null -ne $pfWhen) { $reference = $pfWhen }
3687	                $recorded = Get-PropertyValue $pf 'retry_after' $null
3688	                if ($null -ne $recorded -and "$recorded") { $rec.RetryAfter = ConvertTo-WhenOffset $recorded }
3689	            } else {
3690	                # older entry: classify its bridge_outcome, lifting an SSE/JSON error payload
3691	                $parsedOutcome = ConvertFrom-ProviderErrorText -Text $outcome
3692	                $rec.Class = Get-ProviderFailureClass "$($parsedOutcome.Code) $outcome"
3693	                $rec.Code = $parsedOutcome.Code
3694	                $rec.Message = $parsedOutcome.Message
3695	            }
3696	            # an entry recorded without retry_after: read the reset time from its message now
3697	            if ($null -ne $rec.RetryAfter) { $rec.RetryAfterBasis = 'ledger' }
3698	            else {
3699	                $rec.RetryAfter = Get-RetryAfter -Message $rec.Message -Reference $reference -ReferenceOffset
3700	                if ($null -ne $rec.RetryAfter) { $rec.RetryAfterBasis = 'message (reference offset)' }
3701	            }
3702	            if ($null -ne $rec.RetryAfter) {
3703	                $rec.RetryAfterIso = Format-OffsetIso $rec.RetryAfter
3704	                $rec.Until = $rec.RetryAfter
3705	            }
3706	            if ($rec.Message.Length -gt 100) { $rec.Message = $rec.Message.Substring(0, 100) }
3707	        }
3708	        $records.Add($rec)
3709	    }
3710	    $sorted = @($records | Sort-Object -Property At -Descending)
3711	    $auth = @($sorted | Where-Object { $_.Ok -or $_.Class -eq 'auth' }) | Select-Object -First 1
3712	    if ($auth -and -not $auth.Ok -and $auth.AgeMinutes -le 24 * 60) { $h.Auth = $auth }
3713	    $quota = @($sorted | Where-Object { $_.Ok -or $_.Class -eq 'quota' }) | Select-Object -First 1
3714	    if ($quota -and -not $quota.Ok) {
3715	        if ($null -ne $quota.RetryAfter) {
3716	            if ($quota.RetryAfter.UtcDateTime -gt $UtcNow) { $h.Quota = $quota }
3717	        } elseif ($quota.AgeMinutes -le 60) {
3718	            $h.Quota = $quota
3719	        }
3720	    }
3721	    $h.QuotaKnown = [bool]($h.Quota -and $null -ne $h.Quota.RetryAfter)
3722	    $h.LastLimit = @($sorted | Where-Object { -not $_.Ok -and $_.Class -eq 'quota' -and $_.AgeMinutes -le 24 * 60 }) | Select-Object -First 1
3723	    $h.LastFailure = @($sorted | Where-Object { -not $_.Ok -and $_.AgeMinutes -le 24 * 60 }) | Select-Object -First 1
3724	    $h.RecentUsable = @($sorted | Where-Object { $_.Ok -and $_.Age -le 60 }) | Select-Object -First 1
3725	    return $h
3726	}
