3728	# ----------------------------------------------------------------------------- reviewer roster
3729	#
3730	# The reviewer roster is an ordered list of reviewers the operator is willing to use, first
3731	# choice first. A JSON file (never created by the bridge):
3732	#   CODEX_CONSULT_ROSTER=<path>   that file; it MUST exist (a roster that is asked for and
3733	#                                 missing refuses the run - it is never skipped silently)
3734	#   CODEX_CONSULT_ROSTER=none     no roster at all, the default file is ignored too
3735	#   unset                         <codex home>/codex-consult-roster.json when it exists;
3736	#                                 absent = no roster: everything behaves as without one
3737	#
3738	#   { "roster_version": 1,
3739	#     "reviewers": [ { "provider": "openai", "model": "gpt-5.1" },
3740	#                    { "provider": "ZAI", "model": "glm-5.3" },
3741	#                    { "provider": "local", "model": "m", "auth": "none",
3742	#                      "codex_config": ["model_catalog_json=~/.codex/catalog.json"] } ] }
3743	#
3744	#   provider      required: a [model_providers.<name>] table of the Codex config
3745	#                 (case-sensitive) or openai
3746	#   model         optional: absent = the model resolves as without a roster (the Codex
3747	#                 config's top-level model)
3748	#   codex_config  optional: key=value items with exactly the -CodexConfig rules
3749	#                 (ConvertFrom-CodexConfigItems)
3750	#   auth          optional, only "none": the endpoint needs no credential (a table without
3751	#                 env_key/bearer token then passes the credential check; a table WITH
3752	#                 env_key still needs the variable)
3753	#   panel         optional, "always" (the default) or "weighty": with -Panel a weighty
3754	#                 reviewer joins only on the weighty purposes (framing, decision,
3755	#                 core-contract, acceptance, stuck) or with -PanelAll. The single-reviewer
3756	#                 walk ignores it.
3757	#   engine        optional (0.4.0), "codex" (the default) or "agy": the CLI that carries the
3758	#                 consultation. For agy the provider is a free label (the lineage's
3759	#                 provider, e.g. "gemini"), the model is REQUIRED (the full id with its
3760	#                 tier), codex_config and auth are refused, and one label names one engine
3761	#                 across the roster. Two entries with the same label and different models
3762	#                 are fine (e.g. a "panel": "weighty" entry on the pro model).
3763	# Anything else - an unknown key, roster_version other than 1, reviewers not an array or
3764	# empty, the same (provider, model) twice, a file that does not parse - makes the roster
3765	# unusable, and the bridge refuses to run (fail-closed: an existing roster is never
3766	# ignored).
3767	#
3768	# Selection (codex-consult.ps1; codex-providers.ps1 shows the same walk):
3769	#   -Provider given   the roster does not select; the first entry of that provider (by
3770	#                     -Model too when several entries name it) supplies its model when
3771	#                     -Model is empty and its codex_config when -CodexConfig is empty
3772	#   -Thread given     the thread's ledger entry fixes the reviewer; its roster entry
3773	#                     supplies codex_config
3774	#   otherwise         the roster is walked in order and the first entry whose preflight is
3775	#                     available is used (Select-RosterReviewer); every skipped entry is
3776	#                     recorded with its reason. None available: refused.
3777	#   -Panel            every available entry (Select-PanelMembers) runs the same brief, one
3778	#                     after another, each as a consultation of its own.
3779	
3780	# Where the roster comes from: { Path ('' when none); FromEnv (CODEX_CONSULT_ROSTER named
3781	# it: it must exist); Disabled (CODEX_CONSULT_ROSTER=none) }.
3782	function Get-RosterPath {
4177	function Find-ThreadEntry {
4178	    param([object[]]$Consults, [string]$Thread)
4179	    $r = [pscustomobject]@{ Entry = $null; N = $null; Error = '' }
4180	    $entries = @($Consults | Where-Object { $null -ne $_ })
4181	    $thread = ([string]$Thread).Trim()
4182	    $match = $null
4183	    for ($i = $entries.Count - 1; $i -ge 0; $i--) {
4184	        if ([string](Get-PropertyValue $entries[$i] 'thread' '') -eq $thread) { $match = $entries[$i]; break }
4185	    }
4186	    if (-not $match) {
4187	        $cand = $null
4188	        for ($i = $entries.Count - 1; $i -ge 0; $i--) {
4189	            if ([string](Get-PropertyValue $entries[$i] 'thread_candidate' '') -eq $thread) { $cand = $entries[$i]; break }
4190	        }
4191	        if ($cand) { $r.Error = "thread $thread has unknown provenance: it is only an unverified rollout candidate of consult n=$(Get-PropertyValue $cand 'n' '?') (that rollout did not contain the run's consultation id); use -Mode new" }
4192	        else { $r.Error = "thread $thread has unknown provenance: it is not in this task's ledger; use -Mode new" }
4193	        return $r
4194	    }
4195	    $n = Get-PropertyValue $match 'n' '?'
4196	    if ($null -eq (Get-PropertyValue $match 'reviewer' $null)) {
4197	        $r.Error = "thread $thread has unknown provenance (recorded before 0.3.0); use -Mode new"; return $r
4198	    }
4199	    if (-not (Get-EntryFingerprint $match)) {
4200	        $r.Error = "thread $thread has unknown provenance: consult n=$n ran with an unresolved reviewer identity ($((Get-EntryReviewer $match).Display)); use -Mode new"; return $r
4201	    }
4202	    $r.Entry = $match
4203	    $r.N = $n
4204	    return $r
4205	}
