4207	# { Mode; Parent; ParentN; Note; Error }. $Mode '' = automatic.
4208	function Select-ParentThread {
4721	function Test-PendingActive {
4722	    param($Record, [string]$Path)
4723	    $state = [string](Get-PropertyValue $Record 'state' '')
4724	    $recHost = [string](Get-PropertyValue $Record 'host' '')
4725	    $otherHost = [bool]($recHost -and -not $recHost.Equals([Environment]::MachineName, [StringComparison]::OrdinalIgnoreCase))
4726	    $what = "state '$state', consult n=$(Get-PropertyValue $Record 'n' '?'), handoff $(Get-PropertyValue $Record 'nn' '?'), started $(Get-PropertyValue $Record 'started' '?')"
4727	    $launcher = [string](Get-PropertyValue $Record 'launcher' '')
4728	    # the CLI the record's run started (0.4.0 `engine`; older records: codex)
4729	    $cli = [string](Get-PropertyValue $Record 'engine' '')
4730	    if (-not $cli) { $cli = 'codex' }
4731	    $pids = New-Object System.Collections.Generic.List[object]
4732	    $cp = 0
4733	    if ([int]::TryParse([string](Get-PropertyValue $Record 'child_pid' ''), [ref]$cp) -and $cp -gt 0) {
4734	        $pids.Add([pscustomobject]@{ pid = $cp; start = (ConvertTo-JsonText (Get-PropertyValue $Record 'child_start_time' '')); name = '' })
4735	    }
4736	    # survivors: { pid, start_time, name } entries; a bare pid (older record) has no
4737	    # start time and is judged by the "looks like codex" rule, never by pid alone.
4738	    foreach ($s in @(Get-PropertyValue $Record 'survivors' @())) {
4739	        $sp = 0
4740	        $sStart = ''
4741	        $sName = ''
4742	        if ($null -ne $s -and $s -is [psobject] -and $s.PSObject.Properties['pid']) {
4743	            [void][int]::TryParse([string]$s.pid, [ref]$sp)
4744	            $sStart = ConvertTo-JsonText (Get-PropertyValue $s 'start_time' '')
4745	            $sName = [string](Get-PropertyValue $s 'name' '')
4746	        } else {
4747	            [void][int]::TryParse([string]$s, [ref]$sp)
4748	        }
4749	        if ($sp -gt 0) { $pids.Add([pscustomobject]@{ pid = $sp; start = $sStart; name = $sName }) }
4750	    }
4751	    $originalNote = Get-PendingOriginalNote $Record
4752	    $inactive = { param($c) [pscustomobject]@{ Active = $false; Message = ''; Check = $(if ($originalNote) { "$c; $originalNote" } else { $c }) } }
4753	    $active = { param($m, $c) [pscustomobject]@{ Active = $true; Message = $(if ($originalNote) { $m.TrimEnd([char]'.') + "; $originalNote." } else { $m }); Check = $c } }
4754	
4755	    if ($state -eq 'reserved') { return (& $inactive "reserved: $cli was never started") }
4756	    if ($pids.Count -gt 0 -and $state -ne 'launching') {
4757	        $pidList = (@($pids | ForEach-Object { $_.pid }) -join ', ')
4758	        if ($otherHost) {
4759	            return (& $active "an interrupted consultation on host $recHost left $cli process(es) pid $pidList ($what); they cannot be checked from this host. Delete $Path only after making sure they are gone." "pids on host $recHost")
4760	        }
4761	        $alive = New-Object System.Collections.Generic.List[string]
4762	        $aliveHow = New-Object System.Collections.Generic.List[string]
4763	        $gone = New-Object System.Collections.Generic.List[string]
4764	        foreach ($entry in $pids) {
4765	            $verdict = Test-RecordedProcess -ProcessId $entry.pid -StartTime $entry.start -Name $entry.name -Launcher $launcher
4766	            if ($verdict.Alive) { $alive.Add("$($entry.pid)"); $aliveHow.Add("$($entry.pid) [$($verdict.How)]") } else { $gone.Add("$($entry.pid) [$($verdict.How)]") }
4767	        }
4768	        if ($alive.Count -gt 0) {
4769	            return (& $active "a previous consultation's $cli process (pid $($alive -join ', ')) is still running ($what). Wait for it to exit or stop it, then retry; $Path keeps its record until then." "pid $($aliveHow -join ', ') alive")
4770	        }
4771	        # Every RECORDED pid is gone - but the record names the launcher (the npm shim on
4772	        # Windows) and the survivors the kill could see; the real codex may be a
