582	    if ($collab.Count -gt 0) { $why.Add("the collab directory changed during the run (by the reviewer or anyone else): $(& $cut ([string[]]@($collab | ForEach-Object { $CollabShown + $_ })))") }
583	    if ($BriefChanged) { $why.Add('the brief changed during the run (by the reviewer or anyone else)') }
