165	# Consult numbers named by a finding's reviewer checks that have no ledger entry
166	# (a consultation that recorded checks and stopped before its ledger write).
167	function Get-OrphanCheckConsults {
168	    param($Finding, [hashtable]$LedgerNs)
169	    $out = New-Object System.Collections.Generic.List[int]
170	    foreach ($rc in @(Get-PropertyValue $Finding 'reviewer_checks' @())) {
171	        $v = 0
172	        if ($rc -and [int]::TryParse([string](Get-PropertyValue $rc 'consult' ''), [ref]$v) -and -not $LedgerNs.ContainsKey($v) -and -not $out.Contains($v)) { $out.Add($v) }
173	    }
174	    return , ([int[]]$out.ToArray())
175	}
